#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

const int MAXN = 12;
const int INF = 1000000009;
const int dr[4] = {0, 1, 0, -1};
const int dc[4] = {1, 0, -1, 0};

int n, t;
char G1[MAXN][MAXN], G2[MAXN][MAXN];
int d[MAXN][MAXN];
bool seen[MAXN][MAXN];

struct Node {
    int r, c;
    Node() {}
    Node(int r, int c) : r(r), c(c) {}
};

void bfs_dist(int sr, int sc) {
    for (int i = 0; i < n; ++i) fill(d[i], d[i] + n, INF);
    memset(seen, 0, sizeof(seen));
    queue<Node> q;
    seen[sr][sc] = true;
    d[sr][sc] = 0;
    q.emplace(sr, sc);
    while (!q.empty()) {
        Node cur = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = cur.r + dr[i], nc = cur.c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && !seen[nr][nc] && isdigit(G1[nr][nc])) {
                seen[nr][nc] = true;
                d[nr][nc] = d[cur.r][cur.c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
}

bool dp[72][12][12][12][12];
bool reachable[12][12][12][12];

int flow_cap[290][290];
int prev_v[290];
bool inq[290];

bool augment_path() {
    memset(inq, 0, sizeof(inq));
    memset(prev_v, 0, sizeof(prev_v));
    queue<int> q;
    inq[0] = true;
    q.push(0);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (u == 2 * n * n + 1) return true;
        for (int v = 0; v <= 2 * n * n + 1; ++v) {
            if (flow_cap[u][v] && !inq[v]) {
                inq[v] = true;
                prev_v[v] = u;
                q.push(v);
            }
        }
    }
    return false;
}

void compute() {
    cin >> n >> t;
    for (int i = 0; i < n; ++i) cin >> G1[i];
    for (int i = 0; i < n; ++i) cin >> G2[i];
    int sr, sc;
    cin >> sr >> sc;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (G1[i][j] == 'Z') {
                sr = i; sc = j;
            }
        }
    }
    bfs_dist(sr, sc);
    memset(dp, 0, sizeof(dp));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(G1[i][j])) {
                dp[0][i][j][i][j] = true;
            }
        }
    }
    for (int step = 0; step < t; ++step) {
        for (int pr = 0; pr < n; ++pr) {
            for (int pc = 0; pc < n; ++pc) {
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (!dp[step][pr][pc][r][c]) continue;
                        if (d[r][c] <= step) continue;
                        for (int k = 0; k < 4; ++k) {
                            int nr = r + dr[k], nc = c + dc[k];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < n && isdigit(G1[nr][nc]) && d[nr][nc] >= step + 1) {
                                dp[step + 1][pr][pc][nr][nc] = true;
                            }
                        }
                    }
                }
            }
        }
    }
    memset(reachable, 0, sizeof(reachable));
    for (int step = 0; step <= t; ++step) {
        for (int pr = 0; pr < n; ++pr) {
            for (int pc = 0; pc < n; ++pc) {
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (dp[step][pr][pc][r][c]) {
                            reachable[pr][pc][r][c] = true;
                        }
                    }
                }
            }
        }
    }
    memset(flow_cap, 0, sizeof(flow_cap));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(G1[i][j])) {
                flow_cap[0][i * n + j + 1] = G1[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(G2[i][j])) {
                flow_cap[n * n + i * n + j + 1][2 * n * n + 1] = G2[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!isdigit(G1[i][j])) continue;
            for (int k = 0; k < n; ++k) {
                for (int l = 0; l < n; ++l) {
                    if (!isdigit(G1[k][l])) continue;
                    if (!reachable[i][j][k][l]) continue;
                    flow_cap[i * n + j + 1][n * n + k * n + l + 1] = INF;
                }
            }
        }
    }
    while (augment_path()) {
        int f = INF;
        for (int u = 2 * n * n + 1; u; u = prev_v[u]) {
            f = min(f, flow_cap[prev_v[u]][u]);
        }
        for (int u = 2 * n * n + 1; u; u = prev_v[u]) {
            flow_cap[prev_v[u]][u] -= f;
            flow_cap[u][prev_v[u]] += f;
        }
    }
    int total_flow = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i) {
        total_flow += flow_cap[i][0];
    }
    cout << total_flow << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    compute();
    return 0;
}
